const std = @import("std");
const mem = std.mem;

pub fn encode(...) mem.Allocator.Error![]u8 {
    const rail_count = @as(usize, rails);
    if (rail_count == 0) {
        return allocator.alloc(u8, 0);
    }
    const last_rail = rail_count - 1;
    const out = try allocator.alloc(u8, msg.len);
    errdefer allocator.free(out);
    var rail: usize = 0;
    for (msg, 0..) |c, i| {
       out[i] = c;
       if (rail == 0 and rail != last_rail) {
          rail += 1;
       } else if (rail == last_rail and rail != 0) {
          rail -= 1;
       }
    }
    return out;
}
```
